  'prompt.deny.interrupted': "The user interrupted you with a new message.",
  'prompt.deny.rejected': "The user rejected it: {text}",
  'prompt.deny.rejectedWithout': "The user rejected it. Try another way or ask them.",
  'prompt.deny.stopped': "Stopped.",
